# এসএসসি সাধারণ গণিত অধ্যায় ৬ (রেখা, কোণ ও ত্রিভুজ) ও ৭ (ব্যবহারিক জ্যামিতি): প্রতি অনুশীলনী ৩০টি
from sqlib import *
import sympy as sp, math
x=sp.symbols('x')
def sol(e): return sorted(sp.solve(e,x),key=float)
# ---- 6.1 ----
assert sol(x+4*x-10-180)==[38] and sol(90-x-(180-x)/4)==[60] and (2*18,3*18)==(36,54) and sol(10*x-360)==[36]
assert sol(3*x+10-(5*x-30))==[20] and sol(2*x+15-(3*x-5))==[20] and sol(3*x+20+2*x+10-180)==[30] and sol(5*x-20-(3*x+30))==[25]
assert sol(x-(180-x)-30)==[105] and abs(30*4-5.5*20)==10 and abs(30*2-5.5*30)==105 and sol(x+2*x+10+3*x-10-360)==[60] and sol(9*x-180)==[20]
assert sol(x-sp.Rational(2,3)*(90-x))==[36] and sol(180-x-3*(90-x))==[45] and sol(270-2*x-130)==[70] and sol(4*x-180)==[45]
